<section class="page-section"><div class="container"><div class="section-title"><div><p class="eyebrow">HÀNH TRÌNH CỦA BẠN</p><h1>Chuyến đi</h1><p>Theo dõi mọi yêu cầu đặt chỗ và trạng thái mới nhất.</p></div><a class="btn btn-primary" href="<?= e(url('/')) ?>">Khám phá thêm</a></div><?php if(!$bookings): ?><div class="empty-state"><h2>Chưa có chuyến đi nào</h2><p>Chỗ ở đầu tiên của bạn đang chờ được khám phá.</p><a class="btn btn-primary" href="<?= e(url('/')) ?>">Tìm chỗ ở</a></div><?php else: ?><div class="booking-list"><?php foreach($bookings as $booking): ?><article class="booking-card"><img src="<?= e(image_url($booking['image_url'])) ?>" alt="<?= e($booking['title']) ?>"><div class="booking-info"><div class="d-flex justify-content-between align-items-start"><div><p class="eyebrow"><?= e($booking['city']) ?></p><h2><?= e($booking['title']) ?></h2></div><span class="status status-<?= e($booking['status']) ?>"><?= e($booking['status']) ?></span></div><p><?= e($booking['check_in']) ?> → <?= e($booking['check_out']) ?> · <?= (int)$booking['guest_count'] ?> khách</p><strong><?= number_format((float)$booking['total_amount'],0,',','.') ?>đ</strong><?php if(in_array($booking['status'],['pending','confirmed'],true)): ?><form class="mt-3" method="post" action="<?= e(url('/bookings/'.$booking['id'].'/cancel')) ?>"><?= csrf_field() ?><input type="hidden" name="reason" value="Thay đổi kế hoạch"><button class="btn btn-outline-danger btn-sm" data-confirm="Bạn chắc chắn muốn hủy booking này?">Hủy booking</button></form><?php elseif($booking['status']==='completed'): ?><form class="review-form mt-3" method="post" action="<?= e(url('/bookings/'.$booking['id'].'/review')) ?>"><?= csrf_field() ?><select class="form-control form-control-sm" name="rating" required><option value="">Số sao</option><option value="5">5 sao</option><option value="4">4 sao</option><option value="3">3 sao</option><option value="2">2 sao</option><option value="1">1 sao</option></select><input class="form-control form-control-sm" name="comment" placeholder="Chia sẻ trải nghiệm" required><button class="btn btn-primary btn-sm">Gửi đánh giá</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></div></section>

